def to_decimal(hex_num, base=16):
    return int(hex_num, base)

def to_hexadecimal(decimal_num, base=16):
    if decimal_num == 0:
        return '0'
    hex_digits = []
    while decimal_num > 0:
        hex_digits.append(str(decimal_num % base))
        decimal_num //= base
    hex_digits.reverse()
    return ''.join(hex_digits)

def count_reductions(start_hex, end_hex):
    start_decimal = to_decimal(start_hex)
    end_decimal = to_decimal(end_hex)
    count = 0
    for num in range(start_decimal, end_decimal + 1):
        digits = set()
        for i in range(8):
            digit = str(num % 256)
            digits.add(digit)
            num = num // 256
        sum = sum(2 ** (7 - i) for i in range(8) if i >= len(digits) and digits)
        for i in range(8):
            num ^= sum
        reduced = num % 256
        if to_hexadecimal(reduced, base=16) in digits:
            count += 1
    return count

