def can_transform(A, B):
    if len(A) != len(B) or len(A[0]) != len(B[0]):
        return -1
    m = len(A)
    n = len(A[0])
    for i in range(n):
        if A[::-1] == B[::-1]:
            return 1
        for j in range(n-1):
            if A[j][i] < A[j+1][i]:
                B[j][i], B[j+1][i] = B[j+1][i], B[j][i]
                break
            elif A[j][i] > A[j+1][i]:
                return -1
    return 1

