from math import comb

def distinct_trees(n):
    if n == 1: return 1
    MOD = 1000000007
    adj = defaultdict(list)
    for i in range(1, 2 * n + 1):
        x, y = map(int, input().split())
        adj[x].append(y)
        adj[y].append(x)

    def dfs(node, parent):
        for neighbor in adj[node]:
            if neighbor != parent:
                dfs(neighbor, node)
        return node

    count = 0
    stack = [1, 1]
    while len(stack) > 0:
        root = stack.pop()
        parent = dfs(root, -1)
        subtrees = 1
        kids = list(adj[root])
        for kid in kids:
            if kid != parent:
                stack.append(kid)
        for kid in stack:
            for child in adj[kid]:
                if child in kids:
                    raise ValueError("Graph is not a tree!")
            if child != parent: 
                subtrees += 1
        if subtrees != 1:
            count = (count + comb(subtrees, 2)) % MOD
            count = count * 2
            count = count % MOD
        if subtrees >= 2:
            return count
    return count
