def is_correct_bracket_sequence(s):
    stack = []
    for char in s:
        if char == '+':
            stack.append('|')
        elif char == '-':
            if not stack:
                return False
            last_char = stack.pop()
            if last_char == '|':
                stack.append(')')
            elif last_char == ')':
                return False
    return stack and stack[-1] == ')'

