from functools import lru_cache
from math import inf

def find_min_time(n, s, sequence):
    @lru_cache(None)
    def dfs(index, time):
        if index == n:
            return time
        minimum = inf
        for i in range(min(n, len(sequence))):
            if index == s:
                minimum = min(minimum, time - 1)
            s = (s + i - index) % n
            minimum = min(minimum, dfs(s, time + 1) + i + 1)

        return minimum

    return dfs(0, 0)

