import itertools
from collections import defaultdict

def tree_connections(n):
    tree_edges = []
    parent = defaultdict(int)
    order = 1

    def get_parent(x):
        if x != parent[x]:
            parent[x] = get_parent(parent[x])
        return parent[x]

    def get_rank(x):
        return 1 + sum(get_rank(ch) for ch in parent[x])

    def merge(x, y):
        rp, rp2 = get_parent(x), get_parent(y)
        if rp == rp2:
            return get_rank(x)
        if get_rank(rp) < get_rank(rp2):
            rp, rp2 = rp2, rp
        parent[x] = y
        return get_rank(rp) + get_rank(rp2)

    for _, bi in sorted(itertools.islice((x, y for x, y in sorted((y, x) for x, y in itertools.product(range(1, 2*n + 1), repeat=2))), 2, 2*(n)),):
        if get_parent(bi) == 0:
            get_parent(bi) = order
            order += 1
            tree_edges.extend(b for x, y in [(bi-1, bi), (bi+1, bi+n)] if x in parent and y in parent)

    return merge, tree_edges

def solve(n):
    _, tree_edges = tree_connections(n)
    total_connections = 4 * n * (n - 1) // 2

    count = 1

    path_edges = set(order for order, going in itertools.groupby(tree_edges) if len(list(itertools.islice(going, n-1))) == n-1)
    if len(path_edges) < 2:
        return count

    del tree_edges[(idx+1)%len(tree_edges)][1]
    to_delete = set(tree_edges[:idx])

    def dfs(v):
        global total_connections, path_edges
        total_connections -= 1 if v in to_delete else count
        start, sample = path_edges.pop(), []
        while start != v:
            ch = (-1) if len(order) < 2 else order[-1]
            sample.append(ch)
            for next_v in tree[order.index(ch)][1]:
                if next_v <= 0 or next_v not in tree and next_v <= 0 or next_v not in tree and next_v <= 0:
                    break
                sample.append(next_v)
    for _, order in sorted(itertools.groupby(itertools.chain(tree_edges, range(1, 2*n + 1)), key=lambda order: (order // n, order % n)):):
        for value in itertools.chain.from_iterable(accumulate(depth) for depth in itertools.zip_longest(Order, order)):
            if len(value) == n and max(depth) < n:
                dfs(depth.pop(0))
            else:
                break
        if len(path_edges) < 2:
            return count
    return count * (result * pow(2, 2 - len(path_edges), mod) - 1)

