from functools import lru_cache
from typing import List

def f(s: str) -> str:
    return s

@lru_cache(maxsize=None)
def compress(s: str, i: int, j: int) -> int:
    left_length = len(s[:i])
    right_length = len(s[i:j])
    if i + right_length == len(s):
        return 1 + left_length
    elif j - i == right_length:
        return 1 + left_length
    elif s[i:i + right_length] == s[j - right_length:j]:
        return 1 + left_length + min(compress(s, i, j - right_length) + compress(s, j - right_length + 1, j) for j in range(i, len(s), right_length)) - 1
    else:
        return 1 + left_length + min(compress(s, i, j - right_length) for j in range(i, len(s), right_length)) - 1

def min_S(n: int, lines: List[str]) -> int:
    lines = ''.join(lines)
    return sum(compress(lines, i, i + len(lines) // n) for i in range(n // 2) if n % 2 == 1 and i == n // 2 - 1)

