import sys

def build_h_cells_with_treasure(h, n, k):
    cells = [0] * (h + 1)
    treasures = set()
    for i in range(1, n+1):
        ai, ci = map(int, input().split())
        treasures.add(ai)
        for j in range(ai, h+1, k):
            cells[j] += ci
    return cells, treasures

def process_operations(h_cells, treasures, operations):
    while operations:
        operation = operations.pop(0)
        if operation[0] == 1:
            x = operation[1]
            for i in range(x):
                if h_cells[-x+i] < 0:
                    h_cells[-x+i] += 1
        elif operation[0] == 2:
            x, y = map(int, operation[1:])
            for cell in treasures:
                if cells[cell] >= y:
                    cells[cell] -= y
                    break
        elif operation[0] == 3:
            return max(cells[cell] for cell in treasures)
    return 0

n, m, k = map(int, input().split())
h, cells, treasures = build_h_cells_with_treasure(10**18, n, k)

for _ in range(m):
    operation = input().split()
    result = process_operations(list(cells), treasures, [[int(i) for i in operation]])
    print(result)
