from collections import defaultdict

def can_be_correct(bracket_sequence):
    n = len(bracket_sequence)
    stack = []
    for i in range(n):
        if bracket_sequence[i] > 0:
            stack.append(bracket_sequence[i])
        elif bracket_sequence[i] < 0:
            if not stack or stack[-1] != -bracket_sequence[i]:
                return False
            stack.pop()
    return not stack

def process_queries(queries, n, bracks):
    results = []
    stack = []
    for query in queries:
        if query[0] == 1:
            t, i = query[1], query[2]
            if t > 0:
                stack.append(t)
            elif t < 0:
                if not stack or stack[-1] != -t:
                    results.append("No")
                else:
                    stack.pop()
        elif query[0] == 2:
            l, r = query[1], query[2]
            bracket_sequence = bracks[l-1:r]
            if not stack or can_be_correct(bracket_sequence):
                results.append("Yes")
            else:
                results.append("No")
    return results

# Read input
n = int(input())
k = int(input())
bracks = [int(input()) for _ in range(n)]
q = int(input())
queries = []
for _ in range(q):
    query = list(map(int, input().split()))
    queries.append(query)

# Process and print results
results = process_queries(queries, n, bracks)
for result in results:
    print(result)
