from sys import stdin

def sort_table(A, B):
    def is_sorted(A):
        for i in range(1, len(A)):
            if A[i-1] > A[i]:
                return True
        return False

    n, m = len(A), len(B[0])

    if is_sorted(A) and is_sorted(B):
        return 0

    for i in range(m):
        if is_sorted([A[j][i] for j in range(n)]) != is_sorted([B[j][i] for j in range(n)]):
            return -1

    return 1

def main():
    for line in stdin:
        n, m = map(int, line.strip().split())
        A = [list(map(int, stdin.readline().strip().split())) for _ in range(n)]
        B = [list(map(int, stdin.readline().strip().split())) for _ in range(n)]

        result = sort_table(A, B)
        if result == -1:
            print(-1)
        else:
            print(result)
            for _ in range(n * m):
                row = stdin.readline().strip()
                print(row)

if __name__ == "__main__":
    main()
