import math

def hex_to_dec(hex_val):
    return int(hex_val, 16)

def count_decreasing(nums):
    count = 0
    for i in range(len(nums) - 1):
        l, r = nums[i], nums[i + 1]
        if l > r:
            return count
        l_dec, r_dec = hex_to_dec(l), hex_to_dec(r)
        l_map, r_map = map(set, bin(l_dec)[2:].zfill(16)), map(set, bin(r_dec)[2:].zfill(16))
        if len(r_map) <= len(l_map):
            count += sum(xor_val.count('1') for xor_val in l_map.difference(r_map))
    return count

q = int(input())

for _ in range(q):
    l, r = input().split()
    total_decreasing = count_decreasing([(hex_to_dec(l), hex_to_dec(r))])
    print(total_decreasing)
